practice.solution:
while True:
    line = input()
    if line.startswith('Final answer:'):
        print(line)
        break
    if line.startswith('Action: calculator(') and line.endswith(')'):
        expr = line[len('Action: calculator('):-1]
        try:
            result = eval(expr, {'__builtins__': {}})
            print(f'Observation: {result}')
        except Exception:
            print('Observation: error')
    else:
        print('Observation: error')
